#!/usr/bin/env node
/**
 * QA Runner — Report Renderer
 *
 * Combines .github/.pipeline-context/qa/<id>.test-plan.json (agent: what the test proves) with
 * .github/.pipeline-context/qa/<id>.result.json (script: the real PASS/FAIL/SKIPPED, from run-qa-gate.js) into
 * docs/agent_output/06-test-gate/qa_<id>.md. The rendered Status is taken directly from the script's result — this
 * renderer does not, and cannot, upgrade a FAIL into a PASS.
 *
 * Usage:
 *   node scripts/render-qa-report.js --all
 *   node scripts/render-qa-report.js --issue ISSUE-001
 */
const fs = require('fs');
const path = require('path');
const {
  OUT_DIR, OUT_README, rel, listStep2Fixes, testPlanPathFor, resultPathFor, reportPathFor,
} = require('./lib/qa');

function statusOf(result) {
  if (result.refused) return 'Refused';
  return result.passed ? 'Passed' : 'Failed';
}

function render(id, title, plan, result) {
  const out = [];
  out.push(`# QA Gate — ${id}`);
  out.push('');
  out.push(`## ${title}`);
  out.push('');
  out.push(`_Generated by the qa-runner agent on ${new Date().toISOString().slice(0, 10)}. Gate run ${result.generatedAt || 'not recorded'}._`);
  out.push('');

  const status = statusOf(result);
  out.push('## At a glance');
  out.push('');
  out.push('| | |');
  out.push('|---|---|');
  out.push(`| **Status** | ${status} |`);
  out.push(`| **New regression test** | \`${plan.test_file}\` |`);
  out.push(`| **Requires a live dependency** | ${plan.requires_live_dependency ? 'yes' : 'no'} |`);
  out.push(`| **Modules exercised** | ${(result.modules || []).map((m) => `\`${m}\``).join(', ') || 'n/a'} |`);
  out.push('');

  out.push('## 1. What the new test proves');
  out.push('');
  out.push(plan.what_it_proves);
  out.push('');
  out.push(`**Mocking strategy:** ${plan.mocking_strategy}`);
  out.push('');

  out.push('## 2. Gate result (deterministic — not an agent judgment)');
  out.push('');
  if (result.refused) {
    out.push(`**Refused.** ${result.reason}`);
  } else if (result.output && !result.steps) {
    out.push(`Stage \`${result.stage}\` failed before any test could run.`);
    out.push('');
    out.push('```');
    out.push(result.output);
    out.push('```');
  } else {
    out.push('| Test | Status | Exit code |');
    out.push('|---|---|---|');
    for (const s of result.steps || []) out.push(`| \`${s.test}\` (${s.module}) | ${s.status} | ${s.exitCode ?? 'n/a'} |`);
    out.push('');
    out.push('<details><summary>Per-test output</summary>');
    out.push('');
    for (const s of result.steps || []) {
      out.push(`**\`${s.test}\`**`);
      out.push('');
      out.push('```');
      out.push(s.output);
      out.push('```');
      out.push('');
    }
    out.push('</details>');
  }
  out.push('');
  out.push('_A SKIPPED test is not a pass — it means this sandbox could not run it (usually a live '
    + 'dependency this repo has no embedded/mocked substitute for). The QA gate never reports a test '
    + 'as passing without having actually executed it._');
  out.push('');

  out.push('---');
  out.push('');
  out.push('Run inside an isolated `git worktree` — applied and removed, the real working tree was never touched.');
  out.push('');
  return out.join('\n');
}

const INDEX_MARKER = '<!-- AUTO-GENERATED TABLE — regenerated by 06_additional-test-execution (QA + build), do not hand-edit below this line -->';

function rewriteIndex() {
  if (!fs.existsSync(OUT_DIR)) return;
  const ids = new Set();
  for (const f of fs.readdirSync(OUT_DIR)) {
    const m = /^(?:qa|build)_(.+)\.md$/i.exec(f);
    if (m) ids.add(m[1]);
  }
  const rows = [...ids].sort((a, b) => a.localeCompare(b, undefined, { numeric: true })).map((id) => {
    const qaFile = path.join(OUT_DIR, `qa_${id}.md`);
    const buildFile = path.join(OUT_DIR, `build_${id}.md`);
    const qaText = fs.existsSync(qaFile) ? fs.readFileSync(qaFile, 'utf8') : null;
    const buildText = fs.existsSync(buildFile) ? fs.readFileSync(buildFile, 'utf8') : null;
    const titleMatch = (qaText && /^##\s+(.+)$/m.exec(qaText)) || (buildText && /^##\s+(.+)$/m.exec(buildText));
    const qaStatusMatch = qaText && /\|\s*\*\*Status\*\*\s*\|\s*([^|]+)\|/.exec(qaText);
    const buildStatusMatch = buildText && /\|\s*\*\*Status\*\*\s*\|\s*([^|]+)\|/.exec(buildText);
    return {
      id,
      title: titleMatch ? titleMatch[1].trim() : '(untitled)',
      qaStatus: qaText ? (qaStatusMatch ? qaStatusMatch[1].trim() : 'unknown') : '_pending_',
      buildStatus: buildText ? (buildStatusMatch ? buildStatusMatch[1].trim() : 'unknown') : '_pending_',
      qaFile: qaText ? `qa_${id}.md` : null,
      buildFile: buildText ? `build_${id}.md` : null,
    };
  });
  const existing = fs.existsSync(OUT_README) ? fs.readFileSync(OUT_README, 'utf8') : testGateReadmeContract();
  const contract = existing.includes(INDEX_MARKER) ? existing.slice(0, existing.indexOf(INDEX_MARKER)) : existing.trimEnd() + '\n\n';
  const table = [INDEX_MARKER, ''];
  if (!rows.length) table.push('_No QA or build gate runs yet._', '');
  else {
    table.push('| ID | Title | QA Status | Build Status | QA report | Build report |', '|---|---|---|---|---|---|');
    for (const r of rows) {
      const qaLink = r.qaFile ? `[${r.qaFile}](./${r.qaFile})` : '_none_';
      const buildLink = r.buildFile ? `[${r.buildFile}](./${r.buildFile})` : '_none_';
      table.push(`| ${r.id} | ${r.title} | ${r.qaStatus} | ${r.buildStatus} | ${qaLink} | ${buildLink} |`);
    }
    table.push('');
  }
  fs.mkdirSync(OUT_DIR, { recursive: true });
  fs.writeFileSync(OUT_README, contract.trimEnd() + '\n\n' + table.join('\n'));
}

function testGateReadmeContract() {
  return `# Additional Test Execution — QA + Build Gate

Deterministic gates run by **\`06_additional-test-execution\`** against every fix a diff was drafted
for (Compiled or Compile Failed alike — both gates compile the module themselves, independently of
the Fix Generator's own separate check):

- **QA gate** (\`qa_<id>.md\`) — drafts one new regression test (mocked, not database-backed — this
  repo has no embedded-MongoDB dependency) and runs it inside an isolated \`git worktree\`.
- **Build gate** (\`build_<id>.md\`) — runs \`mvn verify\` plus a dependency-tree diff inside another
  isolated \`git worktree\`. **No agent-authored content at all** — every line comes straight from
  the gate script (deterministic CI/CD execution, not open-ended agentic reasoning).

## Reading Status

- **Passed** — ran for real and exited 0.
- **Failed** — something exited non-zero, or the patch/test diff didn't apply. Never overridden.
- **Refused** — the linked fix report's Status was \`Refused\` (the Fix Generator never drafted a
  diff at all).

A \`SKIPPED\` individual QA test inside a Passed report means this sandbox lacks the dependency that
test needs (commonly a live MongoDB) — it is not counted as a failure, but it is not a pass either.
A build **Failed** whose errors sit outside the fix's own changed files may be this machine's known
JDK/Lombok toolchain mismatch — cross-check before blaming the patch.

`;
}

function parseArgs(argv) {
  const args = {};
  for (let i = 0; i < argv.length; i += 1) { const a = argv[i]; if (a === '--issue' || a === '-i') args.issue = argv[++i]; else if (a === '--all' || a === '-a') args.all = true; }
  return args;
}

function renderOne(id) {
  const planFile = testPlanPathFor(id);
  if (!fs.existsSync(planFile)) throw new Error(`No test plan at ${rel(planFile)}.`);
  const plan = JSON.parse(fs.readFileSync(planFile, 'utf8'));

  const resultFile = resultPathFor(id);
  if (!fs.existsSync(resultFile)) throw new Error(`No gate result at ${rel(resultFile)}. Run run-qa-gate.js --issue ${id} first.`);
  const result = JSON.parse(fs.readFileSync(resultFile, 'utf8'));

  const fixes = listStep2Fixes();
  const fix = fixes.find((f) => f.id === id) || { title: id };

  const target = reportPathFor(id);
  fs.mkdirSync(path.dirname(target), { recursive: true });
  fs.writeFileSync(target, render(id, fix.title, plan, result));
  return { id, status: statusOf(result), report: rel(target) };
}

function main() {
  const args = parseArgs(process.argv.slice(2));
  if (args.all) {
    const targets = listStep2Fixes();
    const written = []; const skipped = [];
    for (const t of targets) {
      try { const r = renderOne(t.id); written.push(r); console.log(`${r.id.padEnd(10)} ${r.status.padEnd(10)} -> ${r.report}`); } catch (err) { skipped.push(t.id); console.error(`${t.id.padEnd(10)} SKIPPED  ${err.message.split('\n')[0]}`); }
    }
    rewriteIndex();
    console.log(`\nWrote ${written.length}/${targets.length} report(s).`);
    if (skipped.length) process.exitCode = 1;
    return;
  }
  if (!args.issue) throw new Error('Missing --issue or --all.');
  const r = renderOne(args.issue);
  rewriteIndex();
  console.log(`QA Runner — wrote ${r.report} (${r.status})`);
}

try { main(); } catch (err) { console.error('Rendering failed:', err.message); process.exit(1); }
